import{_ as e,o as a,c as s,a0 as c}from"./chunks/framework.DhQjJcnt.js";const u=JSON.parse('{"title":"Skill: /spec","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/spec.md","filePath":"references/skills/spec.md"}'),i={name:"references/skills/spec.md"};function t(o,n,l,d,p,r){return a(),s("div",null,[...n[0]||(n[0]=[c(`<h1 id="skill-spec" tabindex="-1">Skill: <code>/spec</code> <a class="header-anchor" href="#skill-spec" aria-label="Permalink to &quot;Skill: \`/spec\`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>spec</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/spec &lt;module-id/slug/draft-id&gt;</code></li><li>Kích hoạt bằng <code>@flowgrid</code> (hoặc tên bot tương ứng) khi cần tạo bản đặc tả ban đầu (design bundle).</li><li>Khi có thêm cờ <code>/legacy</code>: Đọc source cũ và ghi <code>specOrigin: legacy</code>.</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>User Prompt (mô tả yêu cầu bằng text).</li><li>Draft ID (ví dụ: <code>1-1-1</code>, <code>2-1-2</code>) hoặc Slug, Module ID (ví dụ: <code>CMP-ADM-002</code>).</li><li>File requirement dạng Markdown (nếu có) được tạo sẵn trong thư mục ứng với ID (ví dụ: <code>01/01/02.md</code>).</li><li>File template mẫu toolkit: <a href="../../../templates/shared/feature.bundle.yaml"><code>templates/shared/feature.bundle.yaml</code></a> (sau <code>flowgrid init</code> copy vào <code>.flowgrid/templates/</code> trên repo dự án).</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>File <code>*.bundle.yaml</code> chứa thông tin chức năng tại thư mục <code>surfaces/&lt;surface&gt;/CMP-*/&lt;numeric-path&gt;/</code>. (Tuân thủ cấu trúc <a href="../../../templates/shared/feature.bundle.yaml">feature.bundle.yaml</a>.)</li><li>Thư mục được tự động sinh dựa trên số của Draft ID.</li><li>Quá trình chạy tool <code>flowgrid split</code> sẽ sinh ra các file trung gian trong <code>ir/</code> và <code>flowgrid render</code> sinh ra <code>ir/generated/spec.md</code>.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Chuyên dùng để khởi tạo hoặc viết đặc tả chi tiết cho một chức năng/màn hình cụ thể (Function Detail).</li><li>Brainstorm 2 mặt dữ liệu cốt lõi: <ul><li><strong>Business:</strong> Khối <code>userStories</code> chuyên sâu (Primary Story, <code>screenAccess</code> hỗ trợ 3 loại: <code>directRoute</code> cho URL trực tiếp, <code>sidebarMenu</code> cho menu trái đa cấp + text label, <code>contextualAction</code> cho nút bấm kích hoạt từ màn hình A, Screen Handoff từ màn nào sang màn nào, 5 kịch bản chi tiết: Tải dữ liệu, Nhập liệu/Validate, Nộp thành công, Ngoại lệ/Lỗi, Tác vụ ngầm, và Acceptance Criteria).</li><li><strong>Kỹ thuật:</strong> Phân định rõ ràng trên từng element giữa <code>meaning</code> (<strong>Ý nghĩa nghiệp vụ</strong>) và <code>purpose</code> (<strong>Mục đích thao tác</strong>).</li></ul></li><li>Mọi rule validation bắt buộc đi kèm trường <code>messages</code> tiếng Việt cụ thể.</li><li>Mọi hành động tương tác (Actions) phải định nghĩa rõ: <code>validateFormBeforeSubmit</code>, <code>feedback</code> (loadingText, disableWhileSubmitting), <code>apiRefs</code>, <code>onSuccess</code> (toast, navigation handoff, backgroundTrigger), <code>onSpecificError</code> (map lỗi 422, 409 conflict, 403), <code>onCommonError</code>.</li><li><strong>Tuyệt đối không</strong> sinh nội dung ra file <code>.md</code> bằng tay, mà phải luôn ghi vào YAML và để engine <code>flowgrid split</code> lo việc chuyển đổi sang <code>ir/spec.yaml</code> và <code>ir/generated/spec.md</code>.</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li><strong>Trước đó:</strong> Không có bắt buộc, thường được gọi trực tiếp đầu tiên khi có yêu cầu (hoặc sau khi chốt <code>business-process</code>).</li><li><strong>Sau đó:</strong><ul><li>Kéo theo <code>/testcase</code> để đội test chuẩn bị kịch bản E2E.</li><li>Sẽ bị review và xác nhận lại bởi <code>/grill-bqa</code> (về Business), <code>/grill-dev</code> (về Gen Code), <code>/grill-docs</code> (Xung đột).</li><li>Update sau này sẽ dùng <code>/update-spec</code>.</li></ul></li></ul><h2 id="chu-y-quan-trong" tabindex="-1">Chú ý quan trọng <a class="header-anchor" href="#chu-y-quan-trong" aria-label="Permalink to &quot;Chú ý quan trọng&quot;">​</a></h2><ul><li><strong>Luật AskQuestion Tech Debt:</strong> Nếu gặp thông tin phân vân, phải hiển thị Form hỏi người dùng (phải bao gồm tuỳ chọn <code>&quot;Log as Tech Debt&quot;</code>). Nếu người dùng chọn ghi nợ, phải đẩy thông tin vào file <code>qa/open/QA-&lt;page-id&gt;-NNNN.yaml</code> thay vì cố tình tự suy diễn (Hallucinate).</li><li>Không được đưa cấu hình CSS cụ thể (màu sắc, border, padding) vào spec trừ khi là case cực kỳ đặc biệt.</li><li>Yêu cầu dùng ngoặc kép hoặc block YAML (<code>|</code>) cho tất cả các chuỗi chứa dấu hai chấm <code>:</code> hoặc ngoặc vuông <code>[]</code>.</li><li>Việc tìm kiếm và sử dụng template có sẵn (Common Pattern như Delete Flow, CRUD) là điều bắt buộc.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Có requirement mới, hoặc refine spec đã có.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/spec</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Surface: {admin-web}</span></span>
<span class="line"><span>Module: {CMP-…}</span></span>
<span class="line"><span>Function slug: {hotel-list}</span></span>
<span class="line"><span>Requirement: {mô tả ngắn: list + search + pagination + row actions}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Tham chiếu:</span></span>
<span class="line"><span>- Common UI: --id {UI-CMN-*} (surfaces/common/code/…)</span></span>
<span class="line"><span>- 1 slug = 1 function; không gộp create/update vào cùng folder</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Scope IN: \`base-docs\` + \`base-tests\`, harness notes</span></span>
<span class="line"><span>Scope OUT: pages/, components/, mocks/, E2E, unit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Làm:</span></span>
<span class="line"><span>1. Nếu ir/design.yaml đã có → verify gap (layout, actions, validation)</span></span>
<span class="line"><span>2. Nếu mới → draft bundle dưới …/CMP-*/&lt;NN…&gt;/</span></span>
<span class="line"><span>3. Testcase round 1 khớp acceptance</span></span>
<span class="line"><span>4. pnpm flowgrid:render &amp;&amp; pnpm flowgrid:publish</span></span>
<span class="line"><span>5. Câu treo → qa/open/QA-… (không openQuestions trên YAML)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Handoff: gap chưa rõ → /grill-with-docs · UI → /prototype</span></span></code></pre></div><p><strong>Variant — tách function slug:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/spec</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Tách slug mới: {hotel-create} từ {hotel-list} trong cùng CMP-*.</span></span>
<span class="line"><span>Chỉ scope create form + validation + API POST. Link dependency trong notes của list.</span></span></code></pre></div><hr>`,23)])])}const g=e(i,[["render",t]]);export{u as __pageData,g as default};
